const D=[
  {n:'int',c:'types',d:'A number with no decimal point, like 3, 0 or -12. Good for counting things.',p:'Make a named value called count that keeps track of how many items are in the cart. Start it at 0.',x:'count = 42'},
  {n:'float',c:'types',d:'A number with a decimal point, like 19.99 or 0.5. Good for prices and measurements.',p:'Store the price as a decimal number so 19.99 keeps its cents.',x:'price = 19.99'},
  {n:'str',c:'types',d:'A piece of text, written inside quotes. Names, messages and sentences are kept this way.',p:'Save the user\'s name as text so I can show it in a greeting.',x:'name = "hello"'},
  {n:'bool',c:'types',d:'A value that can only be True or False. Good for yes or no questions, like whether someone is logged in.',p:'Add a yes or no value called is_active. Make it True when the account is on and False when it is off.',x:'is_active = True'},
  {n:'None',c:'types',d:'Python\'s way of saying "nothing here yet". It marks a spot that has no value at all.',p:'Start result off empty, with no value at all, until the search finishes.',x:'result = None'},
  {n:'type()',c:'types',d:'Tells you what kind of thing a value is, such as a number or a piece of text.',p:'Show me what kind of value this is. I think it is text and not a number.',x:'type(42)  # <class \'int\'>'},
  {n:'if / elif / else',c:'flow',d:'Lets your code make a choice. It tests one thing, then the next, and falls back to a default when nothing matches.',p:'Print a different message when the number is positive, zero or negative.',x:'if x > 0:\n    print("positive")\nelif x == 0:\n    print("zero")\nelse:\n    print("negative")'},
  {n:'for loop',c:'flow',d:'Walks through every item in a list or other group, one at a time, and runs the same code on each.',p:'Go through my list of names and print each one on its own line.',x:'for item in items: print(item)'},
  {n:'while loop',c:'flow',d:'Keeps repeating the same code as long as something stays true, then stops.',p:'Keep asking for the password until the user types the right one.',x:'while count > 0: count -= 1'},
  {n:'break / continue',c:'flow',d:'Two ways to cut in on code that repeats. One stops the repeating for good. The other skips what is left of the current turn and starts the next turn.',p:'Stop searching the list as soon as you find the target, and skip over any blank entries.',x:'if x == target: break'},
  {n:'pass',c:'flow',d:'A word that does nothing. You put it where Python needs some code but you have not written it yet.',p:'Leave this part empty for now, with a do-nothing line in it, so the file still runs.',x:'def todo(): pass'},
  {n:'match / case',c:'flow',d:'Compares one value with a list of options. It runs the code for the first option that fits. Neater than writing one "if" after another.',p:'Use match/case on the code a website sends back: 200 is fine, 404 is a missing page, anything else is an error.',x:'match status:\n    case 200: show_page()\n    case 404: show_not_found()\n    case _: show_error()'},
  {n:'def',c:'func',d:'The word that starts a new function, which is a named block of code you can run again whenever you need it.',p:'Make a function called greet that takes a name and gives back a hello message.',x:'def greet(name): return f"Hi {name}"'},
  {n:'return',c:'func',d:'Sends the answer back out of a function, so the rest of your code can use it. The function stops right there.',p:'Make the function give back the doubled number instead of just printing it.',x:'def double(x): return x * 2'},
  {n:'lambda',c:'func',d:'A tiny function with no name, written on a single line. Handy when you need a small one just once.',p:'Give me a tiny one-line function that multiplies a number by itself.',x:'square = lambda x: x ** 2'},
  {n:'*args / **kwargs',c:'func',d:'Lets a function take any number of extra inputs. One star gathers the ones given by themselves, like 5. Two stars gather the ones given with a label, like size=5.',p:'Let this function take as many extra inputs as I give it, with or without labels.',x:'def func(*args, **kwargs): ...'},
  {n:'decorators',c:'func',d:'A line starting with @ above a function that adds something extra to it, like timing it, without changing its code.',p:'Write a @timer decorator that prints how long each slow function takes to run.',x:'@timer\ndef slow_func(): ...'},
  {n:'generators',c:'func',d:'A function that hands out results one at a time, only when asked, instead of building the whole list first.',p:'Read this huge file and hand me one line at a time, so the computer never holds the whole file at once.',x:'def count_up(n): yield from range(n)'},
  {n:'type hints',c:'func',d:'Little notes you can add to a function. They say what kind of value goes in, like text, and what kind comes out. They help you spot mistakes early.',p:'Add type hints so it is clear that greet takes text and gives back text.',x:'def greet(name: str) -> str: ...'},
  {n:'list',c:'collect',d:'An ordered group of items you can change. You can add, remove and reorder them. It is Python\'s everyday choice.',p:'Keep my shopping items in order, and let me add or remove items later.',x:'items = [1, 2, 3]; items.append(4)'},
  {n:'dict',c:'collect',d:'Stores pairs: a label and the value that goes with it. You look things up by the label, like a name in a phone book.',p:'Store the user\'s name and age so I can look up each detail by its label.',x:'user = {"name": "Jo", "age": 30}'},
  {n:'tuple',c:'collect',d:'An ordered group of items that cannot change once made. Good for fixed pairs like map coordinates.',p:'Store the x and y position as a fixed pair that nothing can change by accident.',x:'point = (10, 20)'},
  {n:'set',c:'collect',d:'A group of items with no duplicates and no order. Very quick at checking whether something is in it.',p:'Collect the tags and drop any duplicates, so each tag appears only once.',x:'tags = {"a", "b", "c"}'},
  {n:'deque',c:'collect',d:'A line of items that is fast to add to or take from at both ends. Good for waiting lines.',p:'Keep the last 10 messages, adding new ones at one end and dropping old ones from the other.',x:'from collections import deque; q = deque()'},
  {n:'defaultdict',c:'collect',d:'Labels and values kept in pairs, like a phone book. When you ask for a label it does not have yet, it adds it with a starting value for you.',p:'Group the words by first letter without checking whether each letter already has a group.',x:'from collections import defaultdict; d = defaultdict(list)'},
  {n:'Counter',c:'collect',d:'Tallies how many times each item appears, such as each word in a text.',p:'Tell me how many times each word appears in this text.',x:'from collections import Counter; Counter("hello")'},
  {n:'slicing',c:'collect',d:'Takes a piece out of a list or a text. You say where to start and where to stop. You can also skip along, like taking every second item.',p:'Give me just items two to four from the list, and also the text written backwards.',x:'items[1:4]; text[::-1]'},
  {n:'.format() / f-strings',c:'strings',d:'Drops your saved values, like a name, straight into a piece of text. That is how you build a message like "Hello Sam".',p:'Build a greeting that puts the user\'s name and age into the sentence.',x:'f"Hello {name}, you are {age}"'},
  {n:'.split() / .join()',c:'strings',d:'One cuts a piece of text into a list of parts. The other glues a list of parts back into one text.',p:'Break this comma separated line into a list, then put it back together with a comma and space between.',x:'"a,b,c".split(","); ", ".join(items)'},
  {n:'.strip()',c:'strings',d:'Removes extra spaces and line breaks from the start and end of a piece of text.',p:'Clean up what the user typed by removing any spaces at the start and end.',x:'text.strip()'},
  {n:'.replace()',c:'strings',d:'Swaps every copy of one bit of text for another, like changing each "old" to "new".',p:'Go through this text and change every "colour" to "color".',x:'text.replace("old", "new")'},
  {n:'.find() / .index()',c:'strings',d:'Tells you where a bit of text first shows up inside a longer one. When it is not there, one gives you -1 and the other stops with an error.',p:'Tell me the position where "world" first shows up in this text, or -1 when it is missing.',x:'text.find("world")  # returns -1 if not found'},
  {n:'.upper() / .lower()',c:'strings',d:'Turns text into ALL CAPITALS or all small letters. Handy for comparing words without caring how they were typed.',p:'Compare the answer to "yes" without caring whether they used capital letters.',x:'if text.lower() == "yes": ...'},
  {n:'.startswith() / .endswith()',c:'strings',d:'Checks whether a piece of text begins with, or finishes with, certain characters. The answer is True or False.',p:'Check that the file name finishes with .py before you try to run it.',x:'if file.endswith(".py"): ...'},
  {n:'open()',c:'fileio',d:'Gets a file ready so your code can read from it or write to it.',p:'Open data.txt for reading so we can load what is inside.',x:'f = open("data.txt", "r")'},
  {n:'with statement',c:'fileio',d:'Uses a file and makes sure it gets closed afterward, even when something goes wrong in between.',p:'Read f.txt in a way that closes the file by itself, even when something goes wrong.',x:'with open("f.txt") as f: data = f.read()'},
  {n:'read / write modes',c:'fileio',d:'A single letter, like r, w or a, that you type when you open a file. It says whether you want to look at the file, wipe and replace it, or add to the end.',p:'Add the new line to the end of out.txt instead of wiping what is already there.',x:'open("out.txt", "w").write("hello")'},
  {n:'json module',c:'fileio',d:'Comes with Python. It reads and saves data written as plain text where every value has a label, like name: Jo. Websites send each other information this way.',p:'Read the settings from d.json and keep them under a name I can use in my code.',x:'import json; data = json.load(open("d.json"))'},
  {n:'csv module',c:'fileio',d:'The built-in tool for reading and saving spreadsheet style files, where each line is a row and commas separate the columns.',p:'Read d.csv one row at a time so I can use each column by its header name.',x:'import csv; csv.reader(open("d.csv"))'},
  {n:'class',c:'oop',d:'A blueprint for your own kind of thing, like Dog or Invoice, keeping its data and the actions it can do together.',p:'Write a Dog class where every dog you create can bark() and get back "Woof".',x:'class Dog:\n    def bark(self):\n        return "Woof"'},
  {n:'__init__',c:'oop',d:'Setup code that runs by itself each time you make a new thing from a class, like a new Dog. It gives that thing its starting values.',p:'Make every new Dog save its name as soon as it is created.',x:'def __init__(self, name): self.name = name'},
  {n:'self',c:'oop',d:'Inside a class, the word that means "this one". When the code runs for one dog, it means that dog and no other.',p:'Store the name on this particular dog, so each dog remembers its own name.',x:'self.name = name'},
  {n:'inheritance',c:'oop',d:'Lets a new class start with everything a parent class already has, so you only write what is different.',p:'Make Dog a kind of Animal so it gets everything Animal can already do.',x:'class Dog(Animal): ...'},
  {n:'@property',c:'oop',d:'Makes a class work a value out fresh every time you ask for it. You still write it like a simple saved value, such as person.full_name.',p:'Add a @property called full_name that joins first and last name, so I can write person.full_name.',x:'@property\ndef full_name(self):\n    return f"{self.first} {self.last}"'},
  {n:'dunder methods',c:'oop',d:'Functions with special names that have two underscores on each side, like __str__. Python runs them by itself at the right moment, such as when you print.',p:'Make printing a user show their name instead of a confusing code.',x:'def __str__(self): return self.name'},
  {n:'dataclasses',c:'oop',d:'A shortcut for making your own kind of thing when it mostly just holds values, like a point with x and y. Python writes the boring setup code for you.',p:'Turn Point into a dataclass with x and y, so I do not have to write the setup code.',x:'@dataclass\nclass Point:\n    x: float\n    y: float'},
  {n:'print()',c:'builtin',d:'Shows text on the screen so you can see what your code is doing.',p:'Show the result on screen with a label in front, like Result: 42.',x:'print(f"Result: {value}")'},
  {n:'len()',c:'builtin',d:'Tells you how many items are in a list, or how many characters are in a piece of text.',p:'Tell me how many items are in the cart list.',x:'len([1, 2, 3])  # 3'},
  {n:'range()',c:'builtin',d:'Gives you a row of numbers to go through one by one, like 0 to 9. You pick where it starts, where it stops and how big each jump is.',p:'Loop over every second number, starting at 0 and stopping before 10.',x:'for i in range(0, 10, 2): ...'},
  {n:'enumerate()',c:'builtin',d:'Lets a loop give you each item together with its position number, so you do not have to keep count yourself.',p:'Print each item in the list with its position number next to it.',x:'for i, val in enumerate(items): ...'},
  {n:'zip()',c:'builtin',d:'Pairs up two lists item by item, so the first goes with the first, the second with the second, and so on.',p:'Go through the names and scores together, so each name lines up with its score.',x:'for a, b in zip(names, scores): ...'},
  {n:'map() / filter()',c:'builtin',d:'One runs the same function on every item. The other keeps only the items that pass a test.',p:'Change every word to capital letters. Then, as a second job, keep only the words longer than three letters.',x:'list(map(str.upper, words))'},
  {n:'sorted()',c:'builtin',d:'Gives you a new list with the items put in order, and leaves the original untouched.',p:'Give me the users in order of age, youngest first, without changing the original list.',x:'sorted(users, key=lambda u: u.age)'},
  {n:'isinstance()',c:'builtin',d:'Checks whether a value is a certain kind of thing, such as a whole number, and answers True or False.',p:'Check that x is a whole number before doing the maths.',x:'isinstance(x, int)  # True'},
  {n:'any() / all()',c:'builtin',d:'Two quick checks on a group. One is True when at least one item passes. The other is True only when every item passes.',p:'Tell me whether at least one number in the list is bigger than 10.',x:'if any(x > 10 for x in nums): ...'},
  {n:'list comprehension',c:'comp',d:'A one-line way to build a new ordered group of items from another one, written inside square brackets.',p:'In one line, take the numbers 0 to 9, keep the ones bigger than 3, double them and give me the list.',x:'[x*2 for x in range(10) if x > 3]'},
  {n:'dict comprehension',c:'comp',d:'A one-line way to build label and value pairs from other data, written inside curly brackets with a colon.',p:'In one line, make new label and value pairs, keeping only the ones with a value above zero.',x:'{k: v for k, v in items if v > 0}'},
  {n:'generator expression',c:'comp',d:'A one-line way to make items from a group, written inside round brackets. Each item is made only when asked for, so they are never all held at once.',p:'Double every number from 0 up to a million and add them all up, without making the full list first.',x:'sum(x*2 for x in range(1000000))'},
  {n:'set comprehension',c:'comp',d:'A one-line way to build a group with no duplicates, written inside curly brackets with no colon.',p:'In one line, collect every different word in the text in lowercase, with no repeats.',x:'{word.lower() for word in text.split()}'},
  {n:'try / except',c:'errors',d:'Lets risky code fail safely. When a line crashes with an error, you catch it and decide what happens next.',p:'Use try/except around the dividing step. When someone divides by zero, handle that one mistake, but do not hide any other errors.',x:'try:\n    result = x / y\nexcept ZeroDivisionError:\n    result = 0'},
  {n:'finally',c:'errors',d:'Code that always runs at the end, whether or not something went wrong. It is the place to tidy up.',p:'Always close the link to where my data is stored at the end, even when saving fails.',x:'conn = connect()\ntry:\n    save(conn)\nfinally:\n    conn.close()'},
  {n:'raise',c:'errors',d:'Makes your code stop and report an error on purpose, when something is not right.',p:'Stop with a clear error message when the input is not valid.',x:'raise ValueError("Invalid input")'},
  {n:'custom exceptions',c:'errors',d:'Your own named kinds of error, so a problem like "not found" gets a clear name of its own.',p:'Make our own error called NotFoundError, to use when the thing we are looking for is missing.',x:'class NotFoundError(Exception): pass'},
  {n:'assert',c:'errors',d:'A quick check you add while building. You say what should be true. When it is not, the code stops right away with an error.',p:'Add a quick check that the list is not empty, with the message "Empty list".',x:'assert len(items) > 0, "Empty list"'},
];

